-- Updating conversations table to include is_archived column  \nALTER TABLE conversations ADD COLUMN is_archived BOOLEAN DEFAULT FALSE;  \nALTER TABLE conversations ADD COLUMN archived_at TIMESTAMP;  \n\n-- Update RLS policies to prevent messages in archived chats  \nCREATE POLICY prevent_archived_messages ON messages  \n  FOR SELECT USING (chat_id NOT IN (SELECT id FROM conversations WHERE is_archived = TRUE));  \n\n-- Add trigger to auto-archive conversations when product is sold   \nCREATE OR REPLACE FUNCTION archive_conversation() RETURNS TRIGGER AS $trigger$  \nBEGIN  \n   UPDATE conversations SET is_archived = TRUE, archived_at = NOW() WHERE id = NEW.conversation_id;  \n   RETURN NEW;  \nEND;  \n$trigger$ LANGUAGE plpgsql;  \n\nCREATE TRIGGER trigger_auto_archive  \n  AFTER INSERT ON product_sales  \n  FOR EACH ROW EXECUTE FUNCTION archive_conversation();